/bin/bash -lc "python3 -c 'import gzip,collections,statistics,sys; f=gzip.open(\"contaminated.rna.q1.fq.gz\",\"rt\"); lens=collections.Counter(); seqs=collections.Counter(); gc=[]; q=[]; km=collections.Counter(); bases=collections.Counter(); n=0; 
while True:
 h=f.readline()
 if not h: break
 s=f.readline().strip(); f.readline(); qual=f.readline().strip(); n+=1; lens[len(s)]+=1; seqs[s]+=1; bases.update(s); gc.append((s.count(\"G\")+s.count(\"C\"))/len(s)); q.extend([ord(c)-33 for c in qual]);
 for i in range(len(s)-20+1): km[s[i:i+20]]+=1
print(\"reads\",n,\"lengths\",lens,\"unique\",len(seqs),\"dup_reads\",sum(v-1 for v in seqs.values() if v>1)); print(\"bases\",bases,\"GC\",sum((k.count(\"G\")+k.count(\"C\"))*v for k,v in seqs.items())/(n*75)); print(\"meanq\",sum(q)/len(q)); print(\"topseq\",seqs.most_common(10)); print(\"top20\",km.most_common(20))'"

/bin/bash -lc "python3 -c 'import collections; f=open(\"unmapped.fa\"); d={};
while True:
 h=f.readline().strip()
 if not h: break
 s=f.readline().strip(); d[s]=d.get(s,0)+1
print(\"unique\",len(d),\"reads\",sum(d.values())); print(\"top\"); [print(n,c) for n,c in collections.Counter(d).most_common(30)]'"
